using Owner=kstation::ControllerInterruptOwner;using Scheduler=kstation::ControllerInterruptScheduler;using Task=kstation::ControllerInterruptTask;
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};Owner owner;if(!owner.bindVerifiedVectors(rom.data(),rom.size())||owner.bindVerifiedVectors(rom.data(),rom.size()))return 1;Task::Credits c{7,7,9,1,1,1,0,1,0,1};uint64_t stages=0,shorts=0,callbacks=0;for(unsigned vector:{28u,53u,54u,60u}){uint64_t pending=uint64_t(1)<<vector;auto a=owner.admit(pending,true);if(a.result!=Scheduler::Admit::Entered||pending||!owner.awaitingAdmission()||owner.awaitingExternal())return 2;auto r=[&](Task::Resource,unsigned){++callbacks;return 0;};auto w=[&](Task::Resource,uint8_t,unsigned){++callbacks;};if(owner.advanceBefore(100,c,r,w,1,false).clocks||callbacks||owner.advanceBefore(100,c,r,w,1,true,true).clocks||callbacks||!owner.settleAdmission(vector==28?0x968:vector==53?0xa64:vector==54?0xb50:0x670)||!owner.awaitingExternal()||!owner.completeExternal()||owner.active())return 3;}for(unsigned vector:{38u,52u,1u})for(unsigned status=0;status<256;++status){uint64_t pending=uint64_t(1)<<vector;auto a=owner.admit(pending,true);if(a.result!=Scheduler::Admit::Entered||!owner.settleAdmission(vector==38?0x92c:vector==52?0xa50:0x140))return 4;std::array<uint8_t,5>m{{uint8_t(status),uint8_t(status),0xff,0xff,0}};auto read=[&](Task::Resource q,unsigned){++callbacks;return m[unsigned(q)];};auto write=[&](Task::Resource q,uint8_t v,unsigned){++callbacks;m[unsigned(q)]=v;};while(owner.active()){auto cost=owner.nextClocks(c);if(!cost)return 5;auto old=callbacks;for(unsigned i=0;i<cost;++i){auto v=owner.advanceBefore(i,c,read,write);if(v.clocks||v.returned||callbacks!=old)return 6;++shorts;}auto step=owner.advanceBefore(cost,c,read,write);if(step.clocks!=cost)return 7;++stages;}if(vector==38&&(m[0]||m[2]||m[3]))return 8;if(vector==52&&(m[1]!=(status&0xc7)||m[4]!=2))return 9;}uint64_t guard=uint64_t(1)<<28;if(owner.admit(guard,false).result!=Scheduler::Admit::NeedSyscr||guard!=(uint64_t(1)<<28))return 16;if(owner.admit(guard,true,true).result!=Scheduler::Admit::UnsupportedMode||owner.admit(guard,true,false,1).result!=Scheduler::Admit::UnsupportedMode||guard!=(uint64_t(1)<<28))return 15;uint64_t unsupported=uint64_t(1)<<61;auto before=unsupported;if(owner.admit(unsupported,true).result!=Scheduler::Admit::Unsupported||unsupported!=before)return 10;for(unsigned i=0;i<Scheduler::Capacity;++i){owner.setMask(Scheduler::Mask::Enabled);uint64_t p=uint64_t(1)<<28;if(owner.admit(p,true).result!=Scheduler::Admit::Entered)return 11;}owner.setMask(Scheduler::Mask::Enabled);uint64_t p=uint64_t(1)<<28;if(owner.admit(p,true).result!=Scheduler::Admit::Capacity||!p)return 12;for(unsigned i=0;i<Scheduler::Capacity;++i)if(!owner.settleAdmission(0x968)||!owner.completeExternal())return 13;if(owner.active())return 14;std::printf("PASS semantic IRQ owner: %llu phases, %llu short budgets, %llu resource callbacks; four explicit child kinds, nesting/capacity/masks\n",(unsigned long long)stages,(unsigned long long)shorts,(unsigned long long)callbacks);}
